import{_ as a,o as t,c as s,ag as i}from"./chunks/framework.DEqXEGcv.js";const r="/images/issues/016/cover-alma-array.jpg",o="/images/issues/016/news-openai-gpt55.png",n="/images/issues/016/news-openai-dell-codex.png",l="/images/issues/016/news-anthropic-stainless.png",p="/images/issues/016/news-github-npm-staged.png",h="/images/issues/016/news-microsoft-maia.png",c="/images/issues/016/world-large-hadron-collider.jpg",g="/images/issues/016/world-duge-bridge.jpg",u="/images/issues/016/world-bhadla-solar-park.jpg",m="/images/issues/016/world-beijing-daxing-airport.jpg",d="/images/issues/016/world-international-space-station.jpg",b="/images/issues/016/tool-stainless.png",f="/images/issues/016/tool-copilot-eclipse.png",_="/images/issues/016/tool-issue-fields.png",A="/images/issues/016/tool-semantic-issue-search.png",C=JSON.parse('{"title":"小七的周刊（第 016 期）：AI 开始回到企业现场","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"小七的周刊（第 016 期）：AI 开始回到企业现场"}],["meta",{"property":"og:description","content":"本周最值得记住的变化，是 AI agent 从模型发布会走向企业数据、私有环境、供应链闸门和真实业务系统。"}],["meta",{"property":"og:image","content":"https://blog.leeseven.com/images/issues/016/cover-alma-array.jpg"}],["meta",{"property":"og:image:secure_url","content":"https://blog.leeseven.com/images/issues/016/cover-alma-array.jpg"}],["meta",{"property":"og:image:type","content":"image/jpeg"}],["meta",{"property":"og:image:width","content":"3840"}],["meta",{"property":"og:image:height","content":"2560"}],["meta",{"property":"og:image:alt","content":"第 016 期封面图：ALMA 射电望远镜阵列分布在阿塔卡马高原"}],["meta",{"name":"twitter:image","content":"https://blog.leeseven.com/images/issues/016/cover-alma-array.jpg"}],["meta",{"itemprop":"image","content":"https://blog.leeseven.com/images/issues/016/cover-alma-array.jpg"}],["meta",{"property":"og:url","content":"https://blog.leeseven.com/issues/issue-016"}]]},"headers":[],"relativePath":"issues/issue-016.md","filePath":"issues/issue-016.md","lastUpdated":1779679456000}'),I={name:"issues/issue-016.md"};function k(q,e,P,x,w,S){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="小七的周刊-第-016-期-ai-开始回到企业现场" tabindex="-1">小七的周刊（第 016 期）：AI 开始回到企业现场 <a class="header-anchor" href="#小七的周刊-第-016-期-ai-开始回到企业现场" aria-label="Permalink to &quot;小七的周刊（第 016 期）：AI 开始回到企业现场&quot;">​</a></h1><p><em>这里记录每周值得分享的科技内容，<strong>每周一发布</strong>（覆盖上一周 5 月 18 日 - 5 月 24 日）。</em></p><hr><h2 id="本期-3-个要点" tabindex="-1">本期 3 个要点 <a class="header-anchor" href="#本期-3-个要点" aria-label="Permalink to &quot;本期 3 个要点&quot;">​</a></h2><ol><li><strong>AI agent 正在从云端演示进入企业现场。</strong> OpenAI 与 Dell 的合作、Anthropic 收购 Stainless，都指向同一件事：agent 的价值越来越依赖它能否安全接近内部数据、代码和业务系统。</li><li><strong>模型竞争开始进入“成本、芯片、治理”三线战场。</strong> GPT-5.5 强调更强、更省 token；DeepSeek 继续价格下探；Anthropic 传出探索 Microsoft Maia 芯片，说明算力供给已经是产品能力的一部分。</li><li><strong>开发者平台在补发布闸门。</strong> npm staged publishing、Copilot issue/search/workflow 能力、OIDC 扩展，都在给更自动化的软件生产补上可回滚、可观察、可分阶段放量的基础设施。</li></ol><hr><h2 id="封面图" tabindex="-1">封面图 <a class="header-anchor" href="#封面图" aria-label="Permalink to &quot;封面图&quot;">​</a></h2><p><img src="'+r+'" alt="ALMA 射电望远镜阵列分布在阿塔卡马高原"></p><p>封面图：智利阿塔卡马高原上的 ALMA 射电望远镜阵列。几十台天线分布协作，像本期主题：AI 不再只是一个单点模型，而是数据、工具、权限和流程共同组成的系统。</p><hr><h2 id="封面主题-ai-开始回到企业现场" tabindex="-1">封面主题：AI 开始回到企业现场 <a class="header-anchor" href="#封面主题-ai-开始回到企业现场" aria-label="Permalink to &quot;封面主题：AI 开始回到企业现场&quot;">​</a></h2><p>过去两年，AI 行业最热闹的部分是模型发布：更长上下文、更高 benchmark、更快推理、更便宜 API。到了这一周，我更想把注意力放在另一个信号上：<strong>AI agent 正在离开“公共演示环境”，回到企业真实系统附近。</strong></p><p>OpenAI 5 月 18 日宣布与 Dell Technologies 合作，把 Codex 带到混合云和本地企业环境。官方说 Codex 每周已有超过 400 万开发者使用，企业不只拿它做代码审查和测试覆盖，也开始把 agent 用在报告、反馈路由、销售跟进和跨业务系统协调。这个表述很关键：agent 的价值不只来自模型多聪明，还来自它离上下文有多近。</p><p>同一天，Anthropic 宣布收购 Stainless。Stainless 做的是 API SDK 生成和开发者体验基础设施，表面看是一次小型工具收购，放在 agent 语境里就更有意思：当 agent 要稳定调用企业内部 API、理解接口契约、生成可靠客户端和文档时，SDK、schema、版本管理这些“脏活”会变得非常值钱。</p><p>这一周还有两个旁证。GitHub 给 npm 增加 staged publishing 和安装时控制，说明软件供应链不再满足于“发布后发现问题再撤”；Reuters 报道 Anthropic 正与 Microsoft 洽谈使用 Maia AI 芯片，说明模型公司在争夺的不只是用户，也是在争夺更稳定、更可控的算力路径。</p><p>我的判断是：接下来一段时间，“能不能部署在我的数据旁边”“能不能走我的审批链”“能不能接我的 API”“能不能分阶段发布和回滚”，会比单纯模型榜单更影响企业采购。对开发者和产品团队来说，这不是抽象的产业新闻，而是工作方式会变：写代码之外，你还要设计 agent 能接触什么、怎样调用、失败时如何停住。</p><p>边界也要讲清楚。私有化、混合云和本地部署不自动等于安全；离数据更近，也意味着误操作和权限扩散的后果更重。真正成熟的 AI 工作流，不是“把模型搬进机房”就结束，而是把身份、日志、密钥、回滚、测试和变更窗口一起设计进去。</p><hr><h2 id="科技与-ai-动态" tabindex="-1">科技与 AI 动态 <a class="header-anchor" href="#科技与-ai-动态" aria-label="Permalink to &quot;科技与 AI 动态&quot;">​</a></h2><h3 id="_1-gpt-5-5-发布-前沿模型开始同时谈能力和效率" tabindex="-1">1. <a href="https://openai.com/index/introducing-gpt-5-5/" target="_blank" rel="noreferrer">GPT-5.5 发布：前沿模型开始同时谈能力和效率</a> <a class="header-anchor" href="#_1-gpt-5-5-发布-前沿模型开始同时谈能力和效率" aria-label="Permalink to &quot;1. [GPT-5.5 发布：前沿模型开始同时谈能力和效率](https://openai.com/index/introducing-gpt-5-5/)&quot;">​</a></h3><p><img src="'+o+'" alt="OpenAI GPT-5.5 发布页面截图"></p><p>OpenAI 在 GPT-5.5 发布中把重点放在“real work”：编码、调试、在线研究、数据分析、文档表格、软件操作和跨工具持续执行。官方称 GPT-5.5 在 Terminal-Bench 2.0 达到 82.7%，并强调它在真实服务中接近 GPT-5.4 的 per-token latency，同时完成同类 Codex 任务所需 token 更少。</p><p>这条信息对开发者的价值不只是“新模型更强”。真正值得观察的是前沿模型开始把效率写进主叙事：同样任务少重试、少 token、少等待，最后都会转成成本和吞吐。边界在于，benchmark 不能替代自己的评测集；团队如果要升级模型，最好拿最近 20 个真实任务做小样本对比，而不是只看发布页表格。</p><h3 id="_2-openai-与-dell-合作-codex-要进混合云和本地企业环境" tabindex="-1">2. <a href="https://openai.com/index/dell-codex-enterprise-partnership/" target="_blank" rel="noreferrer">OpenAI 与 Dell 合作：Codex 要进混合云和本地企业环境</a> <a class="header-anchor" href="#_2-openai-与-dell-合作-codex-要进混合云和本地企业环境" aria-label="Permalink to &quot;2. [OpenAI 与 Dell 合作：Codex 要进混合云和本地企业环境](https://openai.com/index/dell-codex-enterprise-partnership/)&quot;">​</a></h3><p><img src="'+n+'" alt="OpenAI 与 Dell Technologies 合作页面截图"></p><p>OpenAI 5 月 18 日宣布与 Dell Technologies 合作，让 Codex 更容易接入 Dell AI Data Platform 和 Dell AI Factory 这类企业已有的数据与算力环境。官方还提到 Codex 的使用场景正在从软件开发扩展到报告、反馈处理、销售跟进和跨业务系统协调。</p><p>这说明 agent 的下一步不是只在浏览器里“替你点点”，而是进入企业数据、文档、代码库、运营知识和系统记录之间。对企业读者来说，试点前要先问四个问题：数据在哪、权限谁批、日志留多久、失败谁负责。对小团队来说，也可以先把这个思路缩小成一个本地规则：agent 只能碰指定目录和测试环境。</p><h3 id="_3-anthropic-收购-stainless-api-基础设施成了-agent-能力的一部分" tabindex="-1">3. <a href="https://www.anthropic.com/news/anthropic-acquires-stainless" target="_blank" rel="noreferrer">Anthropic 收购 Stainless：API 基础设施成了 agent 能力的一部分</a> <a class="header-anchor" href="#_3-anthropic-收购-stainless-api-基础设施成了-agent-能力的一部分" aria-label="Permalink to &quot;3. [Anthropic 收购 Stainless：API 基础设施成了 agent 能力的一部分](https://www.anthropic.com/news/anthropic-acquires-stainless)&quot;">​</a></h3><p><img src="'+l+'" alt="Anthropic 收购 Stainless 页面截图"></p><p>Anthropic 5 月 18 日宣布收购 Stainless。Stainless 的核心能力是从 API 规范生成高质量 SDK、文档和开发者体验组件。Anthropic 在公告中直接把这件事放进 agent 叙事里：前沿 AI 正从回答问题转向行动，而行动能力取决于它能接触到哪些系统。</p><p>这比普通收购更值得开发者注意。过去 API 文档和 SDK 常被当成“开发者关系”的边角料；现在它们会影响 agent 能否稳定调用工具、理解错误、保持版本兼容。边界在于，好的 SDK 不能自动解决授权和业务语义问题，但它能显著降低 agent 把接口用错的概率。</p><h3 id="_4-github-给-npm-加-staged-publishing-供应链开始补-灰度发布" tabindex="-1">4. <a href="https://github.blog/changelog/2026-05-22-staged-publishing-and-new-install-time-controls-for-npm/" target="_blank" rel="noreferrer">GitHub 给 npm 加 staged publishing：供应链开始补“灰度发布”</a> <a class="header-anchor" href="#_4-github-给-npm-加-staged-publishing-供应链开始补-灰度发布" aria-label="Permalink to &quot;4. [GitHub 给 npm 加 staged publishing：供应链开始补“灰度发布”](https://github.blog/changelog/2026-05-22-staged-publishing-and-new-install-time-controls-for-npm/)&quot;">​</a></h3><p><img src="'+p+'" alt="GitHub npm staged publishing 页面截图"></p><p>GitHub 5 月 22 日宣布 npm staged publishing 和新的安装时控制。staged publishing 允许包维护者先把新版本发布到受控阶段，再逐步进入普通安装路径；安装侧控制则帮助用户限制可安装的包版本或条件。</p><p>这很像把互联网产品的灰度发布思路搬进包管理器。AI 参与代码和依赖升级越多，供应链越需要“慢一点、可回滚、可观察”的机制。它不能消灭恶意包和账号被盗，但能减少一次错误发布瞬间影响所有下游的概率。维护者这周可以先检查自己的 npm 发布权限、2FA 和撤回流程。</p><h3 id="_5-anthropic-探索-microsoft-maia-模型公司开始认真找第二条算力路" tabindex="-1">5. <a href="https://www.reuters.com/technology/anthropic-talks-use-microsofts-ai-chips-information-reports-2026-05-21/" target="_blank" rel="noreferrer">Anthropic 探索 Microsoft Maia：模型公司开始认真找第二条算力路</a> <a class="header-anchor" href="#_5-anthropic-探索-microsoft-maia-模型公司开始认真找第二条算力路" aria-label="Permalink to &quot;5. [Anthropic 探索 Microsoft Maia：模型公司开始认真找第二条算力路](https://www.reuters.com/technology/anthropic-talks-use-microsofts-ai-chips-information-reports-2026-05-21/)&quot;">​</a></h3><p><img src="'+h+'" alt="Microsoft Azure Maia 100 介绍页面截图"></p><p>Reuters 5 月 21 日援引 The Information 报道称，Anthropic 正与 Microsoft 洽谈使用 Maia AI 芯片。Microsoft 早前公开过 Azure Maia 100，这是面向 Azure AI 基础设施的自研 AI accelerator。</p><p>这条新闻的重点不是 Anthropic 马上会换掉谁，而是大模型公司越来越需要多供应商、多芯片、多云路径。算力不只是采购成本，也会影响模型上线速度、推理价格、区域可用性和企业谈判空间。边界是，谈判不等于落地，Maia 的真实竞争力也要看规模部署后的吞吐、软件栈和总成本。</p><hr><h2 id="世界之最" tabindex="-1">世界之最 <a class="header-anchor" href="#世界之最" aria-label="Permalink to &quot;世界之最&quot;">​</a></h2><h3 id="_1-世界最大粒子加速器-大型强子对撞机" tabindex="-1">1. 世界最大粒子加速器：大型强子对撞机 <a class="header-anchor" href="#_1-世界最大粒子加速器-大型强子对撞机" aria-label="Permalink to &quot;1. 世界最大粒子加速器：大型强子对撞机&quot;">​</a></h3><p><img src="'+c+'" alt="大型强子对撞机探测器内部照片"></p><p><em>大型强子对撞机，位于 CERN，地下环形隧道周长约 27 公里。</em></p><p>LHC 的“最”不是单台机器有多大，而是数千人、探测器、低温系统、数据管线和国际协作共同运转。企业 AI 也会越来越像这种大科学装置：真正的能力来自长期可维护的系统。</p><h3 id="_2-世界最高桥-北盘江第一桥" tabindex="-1">2. 世界最高桥：北盘江第一桥 <a class="header-anchor" href="#_2-世界最高桥-北盘江第一桥" aria-label="Permalink to &quot;2. 世界最高桥：北盘江第一桥&quot;">​</a></h3><p><img src="'+g+'" alt="北盘江第一桥跨越峡谷"></p><p><em>北盘江第一桥，又称都格北盘江大桥，桥面到谷底高度约 565 米。</em></p><p>它把高速路架在极深峡谷之上，难点不只是跨度和高度，还有施工组织、风环境和长期巡检。AI agent 要跨进企业现场，也是在类似的“深谷”上架桥：权限、数据和责任都不能掉下去。</p><h3 id="_3-世界最大太阳能园区之一-bhadla-solar-park" tabindex="-1">3. 世界最大太阳能园区之一：Bhadla Solar Park <a class="header-anchor" href="#_3-世界最大太阳能园区之一-bhadla-solar-park" aria-label="Permalink to &quot;3. 世界最大太阳能园区之一：Bhadla Solar Park&quot;">​</a></h3><p><img src="'+u+'" alt="Bhadla Solar Park 卫星图"></p><p><em>Bhadla Solar Park，位于印度拉贾斯坦邦沙漠地区，是全球最大太阳能园区之一。</em></p><p>从卫星视角看，太阳能园区像把无数小模块铺成一张巨大计算网。它和企业 AI 的启发很接近：规模化不靠单点奇迹，而靠标准化单元、并网、维护和调度。</p><h3 id="_4-世界最大单体航站楼之一-北京大兴国际机场航站楼" tabindex="-1">4. 世界最大单体航站楼之一：北京大兴国际机场航站楼 <a class="header-anchor" href="#_4-世界最大单体航站楼之一-北京大兴国际机场航站楼" aria-label="Permalink to &quot;4. 世界最大单体航站楼之一：北京大兴国际机场航站楼&quot;">​</a></h3><p><img src="'+m+'" alt="北京大兴国际机场航站楼航拍照片"></p><p><em>北京大兴国际机场航站楼以集中式放射布局闻名，是超大型单体航站楼代表。</em></p><p>航站楼的复杂性在于把安检、登机、行李、交通和人流压进同一个空间里协调。企业 AI 进入现场后，也会遇到这种多流程汇合：入口统一只是开始，调度和异常处理才是关键。</p><h3 id="_5-世界最大人造太空结构-国际空间站" tabindex="-1">5. 世界最大人造太空结构：国际空间站 <a class="header-anchor" href="#_5-世界最大人造太空结构-国际空间站" aria-label="Permalink to &quot;5. 世界最大人造太空结构：国际空间站&quot;">​</a></h3><p><img src="'+d+'" alt="国际空间站在轨照片"></p><p><em>国际空间站由多个国家长期协作建造和运行，是低地球轨道上的模块化巨型系统。</em></p><p>它最有启发的不是“在太空很大”，而是模块对接、持续维护和跨组织协作。AI agent 如果要进入真实业务，也需要像空间站一样：能扩展、能维修、能交接，而不是一次性演示。</p><hr><h2 id="开源工具" tabindex="-1">开源工具 <a class="header-anchor" href="#开源工具" aria-label="Permalink to &quot;开源工具&quot;">​</a></h2><h3 id="_1-stainless-把-api-规范变成可维护的-sdk" tabindex="-1">1. <a href="https://www.stainless.com/" target="_blank" rel="noreferrer">Stainless：把 API 规范变成可维护的 SDK</a> <a class="header-anchor" href="#_1-stainless-把-api-规范变成可维护的-sdk" aria-label="Permalink to &quot;1. [Stainless：把 API 规范变成可维护的 SDK](https://www.stainless.com/)&quot;">​</a></h3><p><img src="'+b+'" alt="Stainless 官网页面截图"></p><p>Stainless 的定位是从 OpenAPI 等规范生成 SDK、文档和开发者体验组件。它适合 API 数量多、语言覆盖多、版本变化快的团队；不适合 API 还没稳定、业务语义主要靠口口相传的小项目。</p><p>这类工具在 agent 时代会更重要。人类可以读一段不完整文档后靠经验补全，agent 更依赖清晰 schema、错误码和一致的客户端行为。小七的判断：API 质量会从“方便开发者”升级成“决定 agent 能不能安全行动”的基础设施。</p><h3 id="_2-github-copilot-for-eclipse-老牌-ide-也在接入-ai-开发流" tabindex="-1">2. <a href="https://github.blog/changelog/2026-05-21-github-copilot-for-eclipse-is-open-source/" target="_blank" rel="noreferrer">GitHub Copilot for Eclipse：老牌 IDE 也在接入 AI 开发流</a> <a class="header-anchor" href="#_2-github-copilot-for-eclipse-老牌-ide-也在接入-ai-开发流" aria-label="Permalink to &quot;2. [GitHub Copilot for Eclipse：老牌 IDE 也在接入 AI 开发流](https://github.blog/changelog/2026-05-21-github-copilot-for-eclipse-is-open-source/)&quot;">​</a></h3><p><img src="'+f+'" alt="GitHub Copilot for Eclipse 页面截图"></p><p>GitHub 5 月 21 日宣布 Copilot for Eclipse 开源。Eclipse 不是这几年最闪亮的 IDE，但在 Java、企业系统、嵌入式和长期维护项目里仍然大量存在。</p><p>这条更新的意义在于，AI 开发工具不能只服务新项目和新编辑器。真正的大量代码在老系统里，那里更需要解释、重构、测试和迁移辅助。适合仍在 Eclipse 工作流里的团队关注；但接入前仍要确认代码隐私、企业策略和插件权限。</p><h3 id="_3-issue-fields-把-issue-从聊天记录变成结构化工作对象" tabindex="-1">3. <a href="https://github.blog/changelog/2026-05-21-issue-fields-are-now-in-public-preview-for-all-organizations/" target="_blank" rel="noreferrer">Issue fields：把 Issue 从聊天记录变成结构化工作对象</a> <a class="header-anchor" href="#_3-issue-fields-把-issue-从聊天记录变成结构化工作对象" aria-label="Permalink to &quot;3. [Issue fields：把 Issue 从聊天记录变成结构化工作对象](https://github.blog/changelog/2026-05-21-issue-fields-are-now-in-public-preview-for-all-organizations/)&quot;">​</a></h3><p><img src="'+_+'" alt="GitHub Issue fields 页面截图"></p><p>GitHub 5 月 21 日把 Issue fields 面向所有组织开放 public preview。它允许团队给 Issue 增加更结构化的字段，让优先级、状态、负责人、客户影响等信息不再散落在正文和评论里。</p><p>这对 AI 协作很实用。agent 要帮你排队、分派、总结和生成报告，结构化字段比自然语言评论更可靠。适合 issue 量较大、经常需要跨团队筛选的组织；小项目不必过度设计，先从 3-5 个真正会用的字段开始。</p><h3 id="_4-semantic-issue-search-让-copilot-chat-理解-相似问题" tabindex="-1">4. <a href="https://github.blog/changelog/2026-05-20-semantic-issue-search-in-copilot-chat/" target="_blank" rel="noreferrer">Semantic issue search：让 Copilot Chat 理解“相似问题”</a> <a class="header-anchor" href="#_4-semantic-issue-search-让-copilot-chat-理解-相似问题" aria-label="Permalink to &quot;4. [Semantic issue search：让 Copilot Chat 理解“相似问题”](https://github.blog/changelog/2026-05-20-semantic-issue-search-in-copilot-chat/)&quot;">​</a></h3><p><img src="'+A+'" alt="GitHub semantic issue search 页面截图"></p><p>Semantic issue search 让 Copilot Chat 可以按语义搜索仓库 Issue，而不只是关键词匹配。对大型项目来说，很多重复 bug、相似需求和历史决策并不会用同一组词描述。</p><p>它适合维护时间长、Issue 历史厚的仓库；不适合把搜索结果当最终事实。更稳的用法是让 agent 先找相似 issue，再由人确认上下文是否真的匹配。小七的判断：这是“项目记忆”产品化的一小步，价值会随着历史数据变多而上升。</p><hr><h2 id="本周冷知识-彩蛋" tabindex="-1">本周冷知识 / 彩蛋 <a class="header-anchor" href="#本周冷知识-彩蛋" aria-label="Permalink to &quot;本周冷知识 / 彩蛋&quot;">​</a></h2><ul><li>🥚 <strong>冷知识 1</strong>：ALMA 阵列的天线可以搬到不同位置，改变“虚拟望远镜”的等效口径；有点像把一组工具按任务重新编排。</li><li>🧠 <strong>冷知识 2</strong>：staged publishing 这个思路在应用发布里很常见，但放到 npm 包生态里特别有意义，因为一个小包的坏版本可能被成千上万个项目自动拉取。</li></ul><hr><h2 id="小七的碎碎念" tabindex="-1">小七的碎碎念 <a class="header-anchor" href="#小七的碎碎念" aria-label="Permalink to &quot;小七的碎碎念&quot;">​</a></h2><p>这周我最明显的感觉是：AI 行业终于开始认真面对“上线以后怎么办”。</p><p>发布页上的模型很光鲜，企业现场里的权限、日志和回滚就朴素多了。但真要干活，往往是这些朴素的东西救命。</p><p>一个 agent 如果只能在演示里聪明，还不算成熟；能在乱糟糟的真实系统里守规矩，才算开始像工具。</p><hr><h2 id="互动钩子" tabindex="-1">互动钩子 <a class="header-anchor" href="#互动钩子" aria-label="Permalink to &quot;互动钩子&quot;">​</a></h2><blockquote><p><strong>本周问题：如果你要把 AI agent 接进团队真实系统，第一条硬规则会写什么：权限、日志、审批，还是回滚？</strong></p></blockquote><hr><h2 id="本周行动清单" tabindex="-1">本周行动清单 <a class="header-anchor" href="#本周行动清单" aria-label="Permalink to &quot;本周行动清单&quot;">​</a></h2><ul><li>[ ] 给一个常用 AI 工具写清楚“允许读什么、允许改什么、必须人工批准什么”。</li><li>[ ] 选 10 个真实任务跑一次模型升级对比，记录质量、耗时、token 和返工次数。</li><li>[ ] 检查一个 npm 包或内部依赖的发布流程，确认 2FA、回滚和 staged/灰度策略。</li><li>[ ] 把仓库 Issue 里的一个高频字段结构化，例如优先级、客户影响或复现状态。</li><li>[ ] 为一个 agent 流程补最小审计记录：输入、动作、验证结果和失败处理。</li></ul><hr><div class="issue-subscribe-cta"><h3 id="📬-喜欢这期内容" tabindex="-1">📬 喜欢这期内容？ <a class="header-anchor" href="#📬-喜欢这期内容" aria-label="Permalink to &quot;📬 喜欢这期内容？&quot;">​</a></h3><p>订阅「小七的周刊」，每周一收到最新一期。</p><div class="issue-cta-buttons"><a href="/feed.xml" class="cta-rss" target="_blank" rel="noopener noreferrer">📡 RSS 订阅</a><a href="https://twitter.com/intent/tweet?text=%E6%8E%A8%E8%8D%90%E3%80%8C%E5%B0%8F%E4%B8%83%E7%9A%84%E5%91%A8%E5%88%8A%E3%80%8D&amp;url=https://blog.leeseven.com/issues/issue-016" class="cta-share" target="_blank" rel="noopener noreferrer">🐦 转发到 Twitter</a><a href="https://github.com/leeseven1211/blog-weekly" class="cta-share" target="_blank" rel="noopener noreferrer">⭐ GitHub</a></div></div>',95)])])}const v=a(I,[["render",k]]);export{C as __pageData,v as default};
